test('pan bounds keep content recoverable at every scale, including distant authored nodes',()=>{for(const s of[.2,1,2])for(const p of[{x:80,y:40},{x:-5000,y:9000}]){const result=boundedView({s,x:1e8,y:-1e8},[p],390,650);assert.equal(result.hit,true);const {view:v}=result;assert.ok(p.x*v.s+v.x<390);assert.ok((p.y+118)*v.s+v.y>0);assert.ok(Number.isFinite(v.x)&&Number.isFinite(v.y));assert.equal(boundedView(v,[p],390,650).hit,false)}});
