test('detached blocks and repeat stacks are inactive, keep stable destinations, and copied layouts are offset',async()=>{const{Engine}=await import('../src/engine.mjs'),{visualStateAt}=await import('../src/visual-state.mjs'),{copyCards,pasteCards}=await import('../src/card-clipboard.mjs');const p=fixture();p.chapters[0].events=[{id:'r',type:'repeat',count:3,blockDetached:true,blockPos:{x:600,y:80}},{id:'v',type:'variable',variable:'score',operation:'add',value:10,blockDetached:true},{id:'re',type:'repeatEnd',loopId:'r',blockDetached:true},{id:'b',type:'background',scene:'other',blockDetached:true},{id:'d',type:'dialogue',text:'有效劇情'}];const e=new Engine(p);assert.equal(e.event.id,'d');assert.equal(e.state.vars.score,0);assert.equal(visualStateAt(p,0,4).scene,'classroom');const record=e.save();record.eventId='r';assert.equal(e.load(record),true);assert.equal(e.event.id,'d');const copies=pasteCards(p,0,4,copyCards(p,0,['r','v','re']));assert.equal(copies[0].blockDetached,true);assert.deepEqual(copies[0].blockPos,{x:630,y:110});assert.equal(copies[2].loopId,copies[0].id)});
