test('reference canvas scales the entire game and all system pages together through device and viewport changes',async()=>{const{dom,w,d,errors}=await setup();try{Object.defineProperty(w,'innerWidth',{value:390,configurable:true});Object.defineProperty(w,'innerHeight',{value:780,configurable:true});w.KoiPlayer.mount(w.__p(),{start:{chapter:0,index:0},previewDevice:'desktop'});await wait();const quick=t=>[...d.querySelectorAll('.game-quick button')].find(b=>b.textContent===t);quick('存檔').click();await wait();const inspect=()=>{const ref=d.querySelector('.game-reference'),surface=d.querySelector('.system-canvas');assert.equal(ref.style.width,'960px');assert.equal(ref.style.height,'540px');assert.equal(surface.style.width,ref.style.width);assert.equal(surface.style.height,ref.style.height);assert.equal(surface.style.transform,ref.style.transform);assert.equal(d.querySelector('.game-overlay').style.height,d.querySelector('.game-stage').style.height);assert.equal(d.querySelector('.game-panel-head'),null);return surface.style.transform};const first=inspect();for(const t of['讀檔','歷史','設定','鑑賞','存檔']){[...d.querySelectorAll('.system-nav button')].find(b=>b.textContent===t).click();await wait();assert.equal(inspect(),first)}Object.defineProperty(w,'innerWidth',{value:780,configurable:true});Object.defineProperty(w,'innerHeight',{value:390,configurable:true});w.dispatchEvent(new w.Event('resize'));await wait();assert.notEqual(inspect(),first);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('ten screen presets stay within the canvas and shared chrome and save slots synchronize without copying page labels',async()=>{const{screenPresets,screenPreset,withScreenLayout,screenLayout,resizeScreenRect}=await import('../src/screen-layout.mjs');assert.equal(Object.keys(screenPresets).length,10);for(const device of['desktop','mobile'])for(const page of['save','load','history','settings','gallery'])for(const id of Object.keys(screenPresets)){const v=screenPreset(page,device,id);for(const e of Object.values(v.elements)){assert.ok(e.x>=0&&e.y>=0&&e.x+e.w<=100.001&&e.y+e.h<=100.001)}assert.equal(Object.keys(v.elements).filter(k=>k.startsWith('slot:')).length,['save','load'].includes(page)?9:0)}const p=fixture(),original=screenLayout(p,'save'),q=withScreenLayout(p,'save','desktop',{elements:{header:{...original.elements.header,x:6,fontSize:31,label:'我的存檔'},'slot:0':{...original.elements['slot:0'],x:7}}});for(const page of['load','history','settings','gallery']){const v=screenLayout(q,page);assert.equal(v.elements.header.x,6);assert.equal(v.elements.header.fontSize,31);assert.notEqual(v.elements.header.label,'我的存檔')}assert.equal(screenLayout(q,'load').elements['slot:0'].x,7);assert.equal(screenLayout(q,'save','mobile').elements.header.x,4);const off={...q,settings:{...q.settings,screenSync:false}},r=withScreenLayout(off,'save','desktop',{color:'#123456'});assert.notEqual(screenLayout(r,'load').color,'#123456');assert.deepEqual(resizeScreenRect({x:20,y:20,w:40,h:30},-10,-10,'nw'),{x:10,y:10,w:50,h:40});assert.deepEqual(resizeScreenRect({x:20,y:20,w:40,h:30},90,90,'se'),{x:20,y:20,w:80,h:80})});
