test('template image upload appears as artwork immediately, preserves aspect ratio and accepts hover artwork',async()=>{const{dom,w,d,errors}=await setup();try{w.__tools('saveScreen');await wait();const input=d.querySelector('.screen-tools input[type=file][accept="image/*"]');Object.defineProperty(input,'files',{value:[new File([new Uint8Array([1,2,3])],'template-image.png',{type:'image/png'})],configurable:true});input.dispatchEvent(new w.Event('change',{bubbles:true}));await wait(250);let p=w.__p(),layout=p.settings.menuTemplates.save,added=layout.extras.at(-1);assert.equal(added.kind,'image');const asset=p.images.find(a=>a.id===added.image);assert.ok(asset);assert.equal(added.imageFit,'contain');assert.ok(Math.abs(added.w*960/(added.h*540)-asset.width/asset.height)<.001);let el=d.querySelector('[data-layout-key="'+added.id+'"]');assert.ok(el.style.backgroundImage.includes('blob:'));const hover=d.querySelector('[aria-label="匯入懸停圖片"]');Object.defineProperty(hover,'files',{value:[new File([new Uint8Array([4,5,6])],'hover-image.png',{type:'image/png'})]});hover.dispatchEvent(new w.Event('change',{bubbles:true}));await wait(250);p=w.__p();added=p.settings.menuTemplates.save.extras.at(-1);assert.ok(added.hoverImage);assert.notEqual(added.image,added.hoverImage);el=d.querySelector('[data-layout-key="'+added.id+'"]');assert.ok(el.style.getPropertyValue('--ui-hover-image').includes('blob:'));assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
