test('r3 KOI code editor precedes events, applies source to shared cards and retains file-local undo/redo',async()=>{const{dom,w,d,errors}=await setup();try{assert.equal(d.querySelector('.modes button').dataset.mode,'code');d.querySelector('[data-mode=code]').click();await wait();assert.equal(d.getElementById('codeEditor').hidden,false);assert.equal(d.getElementById('eventList').hidden,true);const editor=d.querySelector('[aria-label="KOI source"]');assert.ok(editor);assert.equal(d.querySelectorAll('.code-tabs button').length,5);const before=editor.value;set(w,editor,'旁白:第一句。;\n等待:0.2;\n停止音訊:音效;\n旁白:第二句。;');await wait();assert.equal(w.__p().programFiles[0].source,editor.value);const key=(key,shift=false)=>editor.dispatchEvent(new w.KeyboardEvent('keydown',{key,ctrlKey:true,shiftKey:shift,bubbles:true,cancelable:true}));key('z');await wait();assert.equal(editor.value,before);key('y');await wait();assert.ok(editor.value.startsWith('旁白:第一句'));button(d,'套用至專案').click();await wait();d.querySelector('[data-answer=ok]')?.click();await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events,e=>e.type),['dialogue','wait','audioStop','dialogue']);button(d,'搜尋取代').click();await wait();set(w,d.querySelector('[aria-label="搜尋程式"]'),'第一句');set(w,d.querySelector('[aria-label="取代內容"]'),'新的第一句');button(d,'全部取代').click();await wait();assert.ok(editor.value.includes('新的第一句'));assert.equal(w.__p().chapters[0].events[0].text,'第一句。');d.querySelector('[data-mode=event]').click();await wait();assert.equal(d.getElementById('codeEditor').hidden,true);assert.equal(d.getElementById('eventList').hidden,false);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('r3 audio continues after a dialogue and explicit stop does not stop the music channel',async()=>{const{dom,w,d,errors}=await setup();try{const instances=[];w.HTMLMediaElement.prototype.play=function(){instances.push(this);return Promise.resolve()};w.HTMLMediaElement.prototype.pause=function(){this.__pauses=(this.__pauses||0)+1};const p=w.__p();p.audio=[{id:'birds',name:'birds.ogg',data:'data:audio/ogg;base64,AQID'},{id:'music',name:'music.ogg',data:'data:audio/ogg;base64,BAUG'}];p.chapters[0].events=[{id:'bgm',type:'music',audio:'music',crossfade:0},{id:'birds',type:'sound',audio:'birds',loop:true},{id:'one',type:'dialogue',text:'一句'},{id:'two',type:'dialogue',text:'兩句'},{id:'stop',type:'audioStop',channel:'sound'},{id:'three',type:'dialogue',text:'三句'}];w.KoiPlayer.mount(p,{start:{chapter:0,index:0}});await wait();const sound=instances.find(a=>a.koiChannel==='sound'),music=instances.find(a=>!a.koiChannel&&a.src.endsWith('BAUG'));assert.ok(sound);assert.ok(music);assert.equal(sound.loop,true);const advance=async()=>{const before=JSON.parse(w.localStorage.getItem('koi-game-pro-resume')).eventId;d.querySelector('.game-tap').click();await wait();if(JSON.parse(w.localStorage.getItem('koi-game-pro-resume')).eventId===before){d.querySelector('.game-tap').click();await wait()}};await advance();assert.equal(JSON.parse(w.localStorage.getItem('koi-game-pro-resume')).eventId,'two');assert.equal(sound.__pauses||0,0);await advance();assert.equal(sound.__pauses,1);assert.equal(music.__pauses||0,0);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
