test('r5 pointer cancellation, Escape, outside drops and mode changes never detach or reorder events',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();const original=JSON.stringify(w.__p().chapters[0].events),program=d.querySelector('.blocks-program');program.getBoundingClientRect=()=>({left:250,top:0,right:1050,bottom:700,width:800,height:700});d.querySelector('.blocks-palette').getBoundingClientRect=()=>({left:70,top:0,right:240,bottom:700,width:170,height:700});const ptr=(el,type,x,y)=>{const ev=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y});Object.defineProperty(ev,'pointerId',{value:19});el.dispatchEvent(ev)};for(const cancel of ['pointercancel','escape','outside','mode']){const grip=d.querySelector('[aria-label="拖移積木 1"]');ptr(grip,'pointerdown',292,74);ptr(grip,'pointermove',800,180);if(cancel==='pointercancel')ptr(grip,'pointercancel',800,180);if(cancel==='escape')d.body.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));if(cancel==='outside')ptr(grip,'pointerup',1200,900);if(cancel==='mode')d.querySelector('[data-mode=event]').click();await wait();assert.equal(JSON.stringify(w.__p().chapters[0].events),original,cancel);assert.equal(d.querySelector('.block-dragging'),null);if(cancel==='mode'){d.querySelector('[data-mode=blocks]').click();await wait()}}assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('r5 changing the chapter resets its block viewport and cancels an unfinished drag',async()=>{const{dom,w,d,errors}=await setup();try{w.__p().chapters.push({id:'second',title:'第二幕',events:[{id:'only-second',type:'dialogue',text:'新的故事'}]});w.__render();d.querySelector('[data-mode=blocks]').click();await wait();const map=d.querySelector('[aria-label="積木小地圖"]'),pointer=(el,type,x,y)=>{const ev=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y});Object.defineProperty(ev,'pointerId',{value:21});el.dispatchEvent(ev)};pointer(map,'pointerdown',1000,1000);await wait();let grip=d.querySelector('[aria-label="拖移積木 1"]');pointer(grip,'pointerdown',300,50);pointer(grip,'pointermove',700,200);assert.ok(d.querySelector('.block-dragging'));d.querySelector('[data-chapter="1"]').click();await wait();assert.equal(d.querySelector('.block-dragging'),null);assert.ok(d.querySelector('.blocks-world').style.transform.includes('translate(16px,16px)'));assert.equal(d.querySelectorAll('.program-block').length,1);assert.equal(d.querySelector('.program-block').dataset.blockId,'only-second');assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});

test('r6 right-click exposes single, following and whole-stack detach with one-step undo',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();const original=Array.from(w.__p().chapters[0].events,e=>e.id);for(const[label,index,expected]of[['拆開單一積木',1,['b']],['拆開此積木與下方積木',1,['b','e']],['拆開整串積木',1,original]]){d.querySelector(`[data-block-index="${index}"]`).dispatchEvent(new w.MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:300,clientY:100}));await wait();button(d,label).click();await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events.filter(e=>e.blockDetached),e=>e.id),expected);d.body.dispatchEvent(new w.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true,cancelable:true}));await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events,e=>e.id),original);assert.ok(w.__p().chapters[0].events.every(e=>!e.blockDetached))}const hat=d.querySelector('.blocks-hat'),first=d.querySelector('[data-block-index="0"]');assert.equal(Number.parseFloat(hat.style.top)+Number.parseFloat(hat.style.height)-Number.parseFloat(first.style.top),4);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('r6 mouse and touch palette drops in left-side blank space create one independent inactive block',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();const program=d.querySelector('.blocks-program');program.getBoundingClientRect=()=>({left:250,top:0,right:1450,bottom:1200,width:1200,height:1200});for(const pointerType of['mouse','touch']){const source=d.querySelector('.palette-block'),before=w.__p().chapters[0].events.length,ptr=(type,x,y)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y});Object.defineProperties(e,{pointerId:{value:31},pointerType:{value:pointerType}});source.dispatchEvent(e)};ptr('pointerdown',90,80);ptr('pointermove',466,900);ptr('pointerup',466,900);source.click();await wait();const es=w.__p().chapters[0].events;assert.equal(es.length,before+1);assert.equal(es.at(-1).blockDetached,true);assert.equal(es.at(-1).blockStack,es.at(-1).id);assert.deepEqual(Array.from(es.filter(e=>!e.blockDetached),e=>e.id),['d','b','e']);d.body.dispatchEvent(new w.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true,cancelable:true}));await wait()}assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('r6 adding inside a floating stack preserves its complete downstream connection, targets and storage',async()=>{const{dom,w,d,errors}=await setup();try{const es=w.__p().chapters[0].events;es.forEach((e,i)=>Object.assign(e,{blockDetached:true,blockStack:'d',blockPos:{x:600,y:100+i*66}}));w.__render();d.querySelector('[data-mode=blocks]').click();await wait();const program=d.querySelector('.blocks-program');program.getBoundingClientRect=()=>({left:250,top:0,right:1450,bottom:1200,width:1200,height:1200});const first=d.querySelector('[data-block-index="0"]'),source=d.querySelector('.palette-block'),x=250+16+parseFloat(first.style.left),y=16+parseFloat(first.style.top)+parseFloat(first.style.height)-4,ptr=(type,x,y)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y});Object.defineProperty(e,'pointerId',{value:32});source.dispatchEvent(e)};ptr('pointerdown',100,80);ptr('pointermove',x,y);ptr('pointerup',x,y);await wait();const added=w.__p().chapters[0].events;assert.equal(added.length,4);assert.equal(added[0].id,'d');assert.equal(added[2].id,'b');assert.equal(added[3].id,'e');assert.ok(added.every(e=>e.blockDetached&&e.blockStack==='d'));assert.deepEqual(Array.from(w.KoiWorkspace.stackSpan(added,0)),Array.from(added,e=>e.id));await w.KoiStorage.saveProject(w.__p());const restored=await w.KoiStorage.loadProject('pro');assert.ok(restored.chapters[0].events.every(e=>e.blockStack==='d'));d.body.dispatchEvent(new w.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true,cancelable:true}));await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events,e=>e.id),['d','b','e']);assert.ok(w.__p().chapters[0].events.every(e=>e.blockStack==='d'));assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('r6 clicking Add in a floating stack joins the new loop without splitting siblings and undo restores exactly once',async()=>{const{dom,w,d,errors}=await setup();try{const es=w.__p().chapters[0].events;es.forEach((e,i)=>Object.assign(e,{blockDetached:true,blockStack:'d',blockPos:{x:600,y:100+i*66}}));w.__render();d.querySelector('[data-mode=blocks]').click();await wait();w.__select(0);await wait();set(w,d.querySelector('[aria-label="新增積木類型"]'),'repeat');d.querySelector('[aria-label="新增積木"]').click();await wait();const added=w.__p().chapters[0].events;assert.equal(added.length,6);assert.deepEqual(Array.from(added,e=>e.type),['dialogue','repeat','wait','repeatEnd','background','end']);assert.ok(added.every(e=>e.blockDetached&&e.blockStack==='d'));assert.equal(added[3].loopId,added[1].id);assert.deepEqual(Array.from(w.KoiWorkspace.stackSpan(added,0)),Array.from(added,e=>e.id));d.body.dispatchEvent(new w.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true,cancelable:true}));await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events,e=>e.id),['d','b','e']);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('r6 Alt-drag extracts a single statement and its original neighbors remain connected',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();const program=d.querySelector('.blocks-program');program.getBoundingClientRect=()=>({left:250,top:0,right:1450,bottom:1200,width:1200,height:1200});d.querySelector('.blocks-palette').getBoundingClientRect=()=>({left:70,top:0,right:240,bottom:1200,width:170,height:1200});const grip=d.querySelector('[aria-label="拖移積木 2"]'),ptr=(type,x,y)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,altKey:true,clientX:x,clientY:y});Object.defineProperty(e,'pointerId',{value:33});grip.dispatchEvent(e)};ptr('pointerdown',300,250);ptr('pointermove',1100,900);ptr('pointerup',1100,900);await wait();const es=w.__p().chapters[0].events;assert.deepEqual(Array.from(es.filter(e=>e.blockDetached),e=>e.id),['b']);assert.deepEqual(Array.from(w.KoiWorkspace.stackSpan(es,0)),['d','e']);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});

test('r6 newly inserted choices lead to the following story event instead of pointing back to themselves',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();w.__select(0);await wait();set(w,d.querySelector('[aria-label="新增積木類型"]'),'choice');d.querySelector('[aria-label="新增積木"]').click();await wait();const es=w.__p().chapters[0].events,choice=es.find(e=>e.type==='choice');assert.ok(choice.options.every(o=>es[o.target]?.id==='b'));const engine=new Engine(w.__p());engine.advance();assert.equal(engine.event.id,choice.id);engine.advance(0);assert.equal(engine.event.id,'e');assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});

test('R7 ten rapid Add clicks retain creation order, unique IDs and all ten undo/redo transactions',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();w.__select(0);await wait();const add=d.querySelector('[aria-label="新增積木"]'),created=[];for(let i=0;i<10;i++){const before=new Set(Array.from(w.__p().chapters[0].events,e=>e.id));add.click();created.push(w.__p().chapters[0].events.find(e=>!before.has(e.id)).id)}await wait();const es=w.__p().chapters[0].events;assert.equal(new Set(es.map(e=>e.id)).size,13);assert.deepEqual(Array.from(es.slice(1,11),e=>e.id),created);for(let i=0;i<10;i++)d.querySelector('#undo').click();await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events,e=>e.id),['d','b','e']);for(let i=0;i<10;i++)d.querySelector('#redo').click();await wait();assert.deepEqual(Array.from(w.__p().chapters[0].events.slice(1,11),e=>e.id),created);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});

test('R7 zoomed and panned mouse and touch single drags preserve their pickup offset in world coordinates',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();w.__select(0);await wait();const program=d.querySelector('.blocks-program');program.getBoundingClientRect=()=>({left:250,top:0,right:1750,bottom:1100,width:1500,height:1100});d.querySelector('.blocks-palette').getBoundingClientRect=()=>({left:70,top:0,right:240,bottom:1100,width:170,height:1100});const ptr=(el,type,x,y,pointerType='mouse',altKey=false)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y,altKey});Object.defineProperties(e,{pointerId:{value:44},pointerType:{value:pointerType}});el.dispatchEvent(e)};for(const kind of['mouse','touch']){for(let i=0;i<10;i++){d.querySelector('[aria-label="縮小積木"]').click();await wait(3)}await wait();ptr(program,'pointerdown',1100,900);ptr(program,'pointermove',1020,840);ptr(program,'pointerup',1020,840);await wait();const tr=d.querySelector('.blocks-world').style.transform,m=tr.match(/translate\(([-\d.]+)px,\s*([-\d.]+)px\) scale\(([-\d.]+)\)/),ox=+m[1],oy=+m[2],z=+m[3],head=d.querySelector('[data-block-id="d"]'),x=parseFloat(head.style.left),y=parseFloat(head.style.top),grip=head.querySelector('.block-grip');ptr(grip,'pointerdown',250+ox+(x+20)*z,oy+(y+12)*z,kind,true);ptr(grip,'pointermove',250+ox+920*z,oy+712*z,kind,true);ptr(grip,'pointerup',250+ox+920*z,oy+712*z,kind,true);await wait();const moved=w.__p().chapters[0].events.find(e=>e.id==='d');assert.equal(moved.blockDetached,true);assert.ok(Math.abs(moved.blockPos.x-900)<.001);assert.ok(Math.abs(moved.blockPos.y-700)<.001);d.querySelector('#undo').click();await wait();d.querySelector('[aria-label="回到起點"]').click();await wait()}assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('R7 shared data changes cancel stale drags and same-ID event type updates its block geometry',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();w.__select(0);await wait();const grip=d.querySelector('[aria-label="拖移積木 1"]'),ptr=type=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:type==='pointerdown'?70:650,clientY:120});Object.defineProperty(e,'pointerId',{value:45});grip.dispatchEvent(e)};ptr('pointerdown');ptr('pointermove');assert.ok(d.querySelector('.block-dragging'));w.__p().chapters[0].events[0].type='background';w.__p().chapters[0].events[0].scene='bg';w.__render();await wait();assert.equal(d.querySelector('.block-dragging'),null);assert.equal(d.querySelector('[data-block-id="d"]').style.height,'310px');ptr('pointerup');await wait();assert.ok(w.__p().chapters[0].events.every(e=>!e.blockDetached));assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('R7 second pointer cannot leave a duplicate palette ghost and cancellation creates no event',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();const source=d.querySelector('.palette-block'),count=w.__p().chapters[0].events.length,ptr=(type,id,primary)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:100,clientY:150});Object.defineProperties(e,{pointerId:{value:id},pointerType:{value:'touch'},isPrimary:{value:primary}});source.dispatchEvent(e)};ptr('pointerdown',46,true);ptr('pointerdown',47,false);assert.equal(d.querySelectorAll('.block-palette-ghost').length,1);ptr('pointercancel',46,true);await wait();assert.equal(d.querySelector('.block-palette-ghost'),null);assert.equal(w.__p().chapters[0].events.length,count);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('R7 edited blocks survive event/flow/code mode changes, source refresh, storage and real player preview',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();w.__select(0);await wait();d.querySelector('[aria-label="新增積木"]').click();await wait();const es=w.__p().chapters[0].events,added=es[1];added.text='資料同步驗收';w.KoiWorkspace.transferStack(w.__p(),0,[added.id],'d',{before:true});w.__render();await wait();const expected=JSON.stringify(w.__p().chapters[0].events);for(const mode of['event','flow','blocks','code','blocks']){d.querySelector(`[data-mode=${mode}]`).click();await wait();if(mode==='code'){button(d,'從事件更新').click();await wait();d.querySelector('[data-answer=ok]')?.click();await wait();assert.ok(d.querySelector('[aria-label="KOI source"]').value.includes('資料同步驗收'))}assert.equal(JSON.stringify(w.__p().chapters[0].events),expected,mode)}await w.KoiStorage.saveProject(w.__p());const saved=await w.KoiStorage.loadProject('pro');assert.equal(JSON.stringify(saved.chapters[0].events),expected);w.__select(0);await wait();d.querySelector('#play').click();await wait(450);assert.ok(d.querySelector('.koi-player'));assert.ok(d.querySelector('.koi-player').textContent.includes('資料同步驗收'));assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('R7 raw KOI import creates a new shared chapter with unique IDs, restores nested blocks and rejects broken import without clearing its draft',async()=>{const{dom,w,d,errors}=await setup();try{w.prompt=()=> '匯入驗收';w.__tools('script');await wait();const raw=[{id:'d',type:'repeat',count:2},{id:'inc',type:'variable',variable:'score',operation:'add',value:1},{id:'close',type:'repeatEnd',loopId:'d'},{id:'finish',type:'dialogue',text:'匯入完成'}].map(e=>'事件:'+JSON.stringify(e)+';').join('\n');set(w,d.querySelector('[aria-label="劇本內容"]'),raw);await wait();button(d,'匯入為新劇情腳本').click();await wait(160);assert.equal(w.__p().chapters.length,2);const imported=w.__p().chapters[1];assert.notEqual(imported.events[0].id,'d');assert.equal(imported.events[2].loopId,imported.events[0].id);assert.equal(new Set(w.__p().chapters.flatMap(c=>Array.from(c.events,e=>e.id))).size,7);d.querySelector('[data-mode=blocks]').click();await wait();assert.equal(d.querySelectorAll('.program-block').length,4);const engine=new Engine(w.__p());engine.reset(1);assert.equal(engine.event.id,'finish');assert.equal(engine.state.vars.score,2);w.__tools('script');await wait();const bad='事件:{"id":"broken","type":"repeat","count":2};';set(w,d.querySelector('[aria-label="劇本內容"]'),bad);await wait();button(d,'匯入為新劇情腳本').click();await wait(130);assert.equal(w.__p().chapters.length,2);assert.equal(d.querySelector('[aria-label="劇本內容"]').value,bad);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
test('R7 dragging on a deep panned canvas stays under the pointer instead of clamping to an obsolete height',async()=>{const{dom,w,d,errors}=await setup();try{d.querySelector('[data-mode=blocks]').click();await wait();Object.assign(w.__p().chapters[0].events[0],{blockDetached:true,blockStack:'d',blockPos:{x:600,y:25000}});w.__select(0);w.__render();await wait();const program=d.querySelector('.blocks-program');program.getBoundingClientRect=()=>({left:250,top:0,right:1450,bottom:1000,width:1200,height:1000});d.querySelector('.blocks-palette').getBoundingClientRect=()=>({left:70,top:0,right:240,bottom:1000,width:170,height:1000});const tr=d.querySelector('.blocks-world').style.transform,m=tr.match(/translate\(([-\d.]+)px,\s*([-\d.]+)px\)/),ox=+m[1],oy=+m[2],grip=d.querySelector('[data-block-id="d"] .block-grip'),ptr=(type,x,y)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,altKey:true,clientX:x,clientY:y});Object.defineProperty(e,'pointerId',{value:50});grip.dispatchEvent(e)};ptr('pointerdown',250+ox+620,oy+25012);ptr('pointermove',250+ox+820,oy+25132);ptr('pointerup',250+ox+820,oy+25132);await wait();const moved=w.__p().chapters[0].events.find(e=>e.id==='d');assert.equal(moved.blockPos.x,800);assert.equal(moved.blockPos.y,25120);assert.equal(errors.length,0,errors.map(e=>e.message).join('\n'))}finally{dom.window.close()}});
